let accountGeneration=0,progressSnapshot=null;
const today=dateKey(new Date());let selected=today,view=new Date(new Date().getFullYear(),new Date().getMonth(),1),exercises=[],filter='All moves',query='',preview=null,records={},storageOK=true,entryMode='plan',period='day';
try{const saved=JSON.parse(localStorage.getItem(workoutCacheKey())||'{}');if(saved&&typeof saved==='object'&&!Array.isArray(saved))for(const [day,rows]of Object.entries(saved))if(/^\d{4}-\d{2}-\d{2}$/.test(day)&&Array.isArray(rows))records[day]=rows.filter(r=>r&&typeof r.id==='string'&&typeof r.done==='boolean').filter((r,i,a)=>a.findIndex(x=>x.id===r.id)===i);}catch{storageOK=false}
