function renderStats(){const total=Object.values(records).flat().filter(r=>r.done).length,xp=total*25+(progressSnapshot?.bonusXP||0),level=Math.floor(xp/200)+1;$('level').innerHTML=`${String(level).padStart(2,'0')} <small>${level<3?'Rookie':level<6?'Challenger':level<10?'Warrior':'Legend'}</small>`;$('xp-text').textContent=`${xp%200} / 200 XP to next level`;$('xp-bar').style.width=`${xp%200/2}%`;const month=dateKey(view).slice(0,7);$('month-workouts').innerHTML=`${Object.entries(records).filter(([d])=>d.startsWith(month)).flatMap(([,rs])=>rs).filter(r=>r.done).length} <small>moves completed</small>`;let streak=0,cursor=new Date(today+'T12:00:00');if(!(records[dateKey(cursor)]||[]).some(r=>r.done))cursor.setDate(cursor.getDate()-1);while((records[dateKey(cursor)]||[]).some(r=>r.done)){streak++;cursor.setDate(cursor.getDate()-1)}$('streak').innerHTML=`${streak} <small>${streak===1?'day':'days'}</small>`}
function exerciseAnimation(e){if(e.prenatal)return e.variants?.prenatal||e.variants?.female||{image:e.image,gif:e.gif};return GymProfile.gender==='female'?e.variants?.female:(e.variants?.male||{image:e.image,gif:e.gif})}
function updatePreviewCharacter(){if(!preview)return;const animation=exerciseAnimation(preview),gender=GymProfile.gender;$('preview-image').hidden=!animation;if(animation)$('preview-image').src=animation.image;$('preview-image').alt=preview.name+(preview.prenatal?' · pregnancy exercise demonstration':' · '+gender+' anime exercise animation');$('preview-group').textContent=preview.prenatal?'Pregnancy · '+(preview.pregnancyCategory||'Exercise'):(gender==='female'?'Female':'Male')+' · '+preview.group}
