$('prev').onclick=()=>{view.setMonth(view.getMonth()-1);renderCalendar();renderStats()};$('next').onclick=()=>{view.setMonth(view.getMonth()+1);renderCalendar();renderStats()};$('today').onclick=()=>selectDay(today);$('search').oninput=e=>{query=e.target.value.trim().toLowerCase();$('exercise-grid').scrollTop=0;renderExercises()};document.querySelector('.dialog-close').onclick=()=>$('exercise-dialog').close();$('exercise-dialog').onclick=e=>{if(e.target===$('exercise-dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close()}};$('preview-add').onclick=()=>add(preview.id);
async function init(){await window.GymCloud?.ready;const generation=accountGeneration;records={};try{records=JSON.parse(localStorage.getItem(workoutCacheKey())||'{}')}catch{}try{const stored=await GymScreenshotStore.getRecords();if(generation===accountGeneration){if(stored&&typeof stored==='object'&&!Array.isArray(stored)){records=stored}else await GymScreenshotStore.putRecords(structuredClone(records));storageOK=true;await GymCalendar.start(records)}}catch{storageOK=false}render();try{const response=await fetch('exercises.json');if(!response.ok)throw Error('Could not load exercise library');exercises=await response.json();const allowed=new Set(exercises.map(e=>e.id));for(const day in records)records[day]=records[day].filter(r=>allowed.has(r.id)||(typeof r.name==='string'&&r.name.trim()));for(const group of ['All moves',...new Set(exercises.flatMap(e=>e.groups||[e.group]))]){const b=document.createElement('button');b.textContent=group;b.className=group===filter?'active':'';b.setAttribute('aria-pressed',String(group===filter));b.onclick=()=>{filter=group;for(const button of $('filters').children){button.classList.toggle('active',button===b);button.setAttribute('aria-pressed',String(button===b))}$('exercise-grid').scrollTop=0;renderExercises()};$('filters').append(b)}render();if(!storageOK){document.querySelector('.save-label').textContent='○ Session only';notify('Browser storage is unavailable. Screenshot imports cannot be saved.')}registerTools();connectScreenshotImport()}catch{$('exercise-grid').innerHTML='<p>The exercise library could not load. <button class="primary" onclick="location.reload()">Retry</button></p>'}}
function registerTools(){const context=document.modelContext;if(!context?.registerTool)return;const life=new AbortController();window.addEventListener('pagehide',()=>life.abort(),{once:true});for(const tool of [{name:'read_workout_calendar',description:'Read workout plans and completion status saved on this device.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({selected,records,exercises:exercises.filter(exerciseAvailable).map(({id,name,group})=>({id,name,group}))})},{name:'add_workouts_to_day',description:'Add exercises to a calendar day without marking them complete.',inputSchema:{type:'object',properties:{date:{type:'string'},exerciseIds:{type:'array',items:{type:'string'}}},required:['date','exerciseIds'],additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>{if(!input||!/^\d{4}-\d{2}-\d{2}$/.test(input.date)||!Array.isArray(input.exerciseIds)||input.exerciseIds.some(id=>!exercises.some(e=>e.id===id&&exerciseAvailable(e))))throw Error('Supply a valid date and known exercise IDs');const d=new Date(input.date+'T12:00:00');if(isNaN(d)||dateKey(d)!==input.date)throw Error('Invalid calendar date');selectDay(input.date);const existing=new Set(rows().map(r=>r.id));records[selected]=[...rows(),...Array.from(new Set(input.exerciseIds)).filter(id=>!existing.has(id)).map(id=>exerciseRecord(id))];save();return{date:selected,workouts:rows()}}}])try{Promise.resolve(context.registerTool(tool,{signal:life.signal})).catch(()=>{})}catch{}}

function minutes(r){return r.done&&GymTracking.mode(r,recordExercise(r))==='time'?Math.max(0,Math.min(1440,Number(r.minutes)||0)):0}
function dayMinutes(key){return(records[key]||[]).reduce((n,r)=>n+minutes(r),0)}
function formatHours(m){return (m/60).toLocaleString(undefined,{maximumFractionDigits:2})+' h'}
function rangeDates(start,count){return Array.from({length:count},(_,i)=>{const d=new Date(start);d.setDate(d.getDate()+i);return dateKey(d)})}
function renderHours(){const day=new Date(selected+'T12:00:00'),week=new Date(day);week.setDate(week.getDate()-week.getDay());const weekKeys=rangeDates(week,7),monthStart=new Date(day.getFullYear(),day.getMonth(),1),monthKeys=rangeDates(monthStart,new Date(day.getFullYear(),day.getMonth()+1,0).getDate());$('day-hours').textContent=formatHours(dayMinutes(selected));$('week-hours').textContent=formatHours(weekKeys.reduce((s,k)=>s+dayMinutes(k),0));$('month-hours').textContent=formatHours(monthKeys.reduce((s,k)=>s+dayMinutes(k),0));$('total-days').textContent=Object.values(records).filter(rs=>rs.some(r=>r.done)).length;
let buckets=[],label='';if(period==='day'){buckets=Array.from({length:24},(_,i)=>({label:String(i).padStart(2,'0'),value:0}));let untimed=0;for(const r of rows()){if(!r.done)continue;const m=minutes(r);if(/^([01]\d|2[0-3]):[0-5]\d$/.test(r.time||'')){buckets[Number(r.time.slice(0,2))].value+=m}else untimed+=m}if(untimed)buckets.push({label:'No time',value:untimed});label='Selected day · hours grouped by workout start time'}else{const keys=period==='week'?weekKeys:monthKeys;buckets=keys.map(key=>({label:period==='week'?new Date(key+'T12:00:00').toLocaleDateString(undefined,{weekday:'short'}):String(Number(key.slice(-2))),value:dayMinutes(key)}));label=period==='week'?'Week of '+week.toLocaleDateString(undefined,{month:'short',day:'numeric'})+' · hours per day':day.toLocaleDateString(undefined,{month:'long',year:'numeric'})+' · hours per day'}
$('chart-label').textContent=label;$('chart-total').textContent=formatHours(buckets.reduce((s,b)=>s+b.value,0));const chart=$('hours-chart');chart.replaceChildren();const max=Math.max(60,...buckets.map(b=>b.value));for(const b of buckets){const col=document.createElement('div');col.className='hour-column';col.setAttribute('aria-label',b.label+': '+formatHours(b.value));col.title=b.label+': '+formatHours(b.value);const val=document.createElement('span');val.className='hour-value';val.textContent=b.value?formatHours(b.value):'';const track=document.createElement('div');track.className='hour-track';const bar=document.createElement('i');bar.style.height=(b.value/max*100)+'%';track.append(bar);const name=document.createElement('span');name.className='hour-label';name.textContent=b.label;col.append(val,track,name);chart.append(col)}const missing=rows().filter(r=>r.done&&GymTracking.mode(r,recordExercise(r))==='time'&&!minutes(r)).length;const strength=GymTracking.strength(rows(),recordExercise);$('day-sets').textContent=strength.sets;$('day-reps').textContent=strength.reps;$('time-note').textContent=missing?`${missing} completed timed activity${missing===1?' needs':'ies need'} a duration. Enter minutes in the daily quest above.`:'Time totals use completed timed activities. Strength totals use completed sets × reps per set. Start time is optional.'}
for(const button of $('period-tabs').children)button.onclick=()=>{period=button.dataset.period;for(const b of $('period-tabs').children){b.classList.toggle('active',b===button);b.setAttribute('aria-pressed',String(b===button))}renderHours()};
function setMode(mode){entryMode=mode;for(const [id,value]of [['mode-plan','plan'],['mode-done','done']]){const b=$(id);b.classList.toggle('active',mode===value);b.setAttribute('aria-pressed',String(mode===value))}renderExercises();renderPreview()}
$('mode-plan').onclick=()=>setMode('plan');$('mode-done').onclick=()=>setMode('done');
function connectScreenshotImport(){GymScreenshotImport.connect({getDay:()=>selected,today,dateKey,getRecords:()=>records,nameOf:r=>recordExercise(r)?.name||r.name||'Workout',setRecords:next=>{const previousProgress=progressSnapshot;records=next;storageOK=true;try{localStorage.setItem(workoutCacheKey(),JSON.stringify(records))}catch{}document.querySelector('.save-label').textContent=GymCalendar.status();GymCalendar.kick();render();window.GymProgress?.announce(previousProgress,progressSnapshot)},selectDay,render,notify,setImportBusy:busy=>{document.querySelector('.save-label').textContent=busy?'○ Saving…':storageOK?GymCalendar.status():'○ Unsaved changes'}});$('screenshot-storage-label').textContent='Screenshot images and recognized text stay on this device. Reviewed activity details sync to your signed-in account.'}
init();




function renderGoals(){
  const p=GymProfile.value;$('training-goal').hidden=!p.completed;if(!p.completed)return;
  const week=new Date(selected+'T12:00:00');week.setDate(week.getDate()-week.getDay());
  const keys=rangeDates(week,7),active=keys.filter(k=>(records[k]||[]).some(r=>r.done)).length,total=keys.reduce((n,k)=>n+dayMinutes(k),0);
  $('goal-week-label').textContent='Week of '+week.toLocaleDateString(undefined,{month:'short',day:'numeric'})+' · Goals you chose for your routine';
  $('goal-days-progress').textContent=active+' / '+p.daysPerWeek+' days';$('goal-days-bar').style.width=Math.min(100,active/p.daysPerWeek*100)+'%';
  $('goal-workout-metric').hidden=p.minutesPerWorkout===null;
  if(p.minutesPerWorkout!==null){$('goal-workout-progress').textContent=Number(dayMinutes(selected).toFixed(2))+' / '+p.minutesPerWorkout+' min';$('goal-workout-bar').style.width=Math.min(100,dayMinutes(selected)/p.minutesPerWorkout*100)+'%'}
  $('goal-week-metric').hidden=p.hoursPerWeek===null;
  if(p.hoursPerWeek!==null){$('goal-week-progress').textContent=Number((total/60).toFixed(2))+' / '+p.hoursPerWeek+' h';$('goal-week-bar').style.width=Math.min(100,total/60/p.hoursPerWeek*100)+'%'}
}
$('edit-goals').onclick=()=>GymProfile.open();
window.addEventListener('gym-account-changed',async()=>{
  const generation=++accountGeneration;GymScreenshotImport.resetAccount();GymCalendar.reset();
  for(const d of document.querySelectorAll('dialog.screenshot-dialog,dialog.screenshot-view-dialog, #exercise-dialog'))if(d.open)d.close();
  records={};render();
  try{const stored=await GymScreenshotStore.getRecords();if(generation!==accountGeneration)return;records=stored||{};storageOK=true;await GymCalendar.start(records);if(generation!==accountGeneration)return;render()}catch{storageOK=false;notify('Player records could not load. Please try reloading.')}
});

window.GymCalendarNames=r=>recordExercise(r)?.name||r.name||r.id;
window.addEventListener('gym-calendar-status',event=>{if(storageOK)document.querySelector('.save-label').textContent=event.detail.text;$('review-sync').hidden=!event.detail.conflicts;});
window.addEventListener('gym-calendar-records',event=>{records=event.detail;try{localStorage.setItem(workoutCacheKey(),JSON.stringify(records))}catch{}render();});

function trackingFields(r,e){
  const fields=document.createElement('div');fields.className='duration-fields workout-fields';
  const mode=GymTracking.mode(r,e),modeLabel=document.createElement('label');modeLabel.textContent='Track ';
  const select=document.createElement('select');select.setAttribute('aria-label','Tracking mode for '+e.name);
  for(const [value,label]of [['reps','Sets & reps'],['time','Time']]){const option=document.createElement('option');option.value=value;option.textContent=label;select.append(option)}
  select.value=mode;select.onchange=()=>{r.tracking=select.value;save()};modeLabel.append(select);fields.append(modeLabel);
  function numberField(key,label,aria,max,step,min='1'){
    const wrapper=document.createElement('label');wrapper.textContent=label+' ';const input=document.createElement('input');
    input.type='number';input.inputMode=step==='1'?'numeric':'decimal';input.min=key==='minutes'?'0':min;input.max=String(max);input.step=step;
    input.value=r[key]??'';input.placeholder='—';input.setAttribute('aria-label',aria+' '+e.name);
    input.onchange=()=>{if(input.value===''&&!input.validity.badInput){r[key]=null;save();return}if(!input.checkValidity()){input.reportValidity();return}r[key]=Number(input.value);if(key==='weight'){r.weightUnit=GymTracking.weightUnit({weightUnit:r.weightUnit||GymProfile.value.weightUnit});r.weightKind=/assisted/i.test(e.name)&&/machine/i.test(e.equipment||'')?'assistance':'load'}save()};
    if(key==='weight')wrapper.className='weight-field';
    wrapper.append(input);fields.append(wrapper);
  }
  if(mode==='reps'){
    numberField('sets','Sets','Sets for',1000,'1');numberField('reps','Reps / set','Reps per set for',1000,'1');
    const total=document.createElement('span');total.className='workout-total';
    const sets=GymTracking.count(r.sets),reps=GymTracking.count(r.reps);
    total.textContent=sets!==null&&reps!==null?sets+' sets × '+reps+' reps = '+sets*reps+' total reps':'Enter '+(r.done?'completed':'planned')+' sets and reps';fields.append(total);
  }else {numberField('minutes','Minutes','Minutes spent on',1440,'0.01');if(e.phase&&!e.prenatal){const note=document.createElement('span');note.className='stretch-duration-note';note.textContent='Suggested: '+(window.GymStretches?.duration(e)||(e.defaultMinutes||1)+' min total')+' · Edit to match your actual time';fields.append(note)}}
  if(GymTracking.supportsWeight(r,e)){
    const assistance=/assisted/i.test(e.name)&&/machine/i.test(e.equipment||'');
    numberField('weight',assistance?'Assistance (optional)':'Weight (optional)',assistance?'Assistance weight for':'Weight for',10000,'any','0');
    const unitLabel=document.createElement('label');unitLabel.className='weight-field';unitLabel.textContent='Weight unit ';
    const unit=document.createElement('select');unit.setAttribute('aria-label','Weight unit for '+e.name);
    for(const [value,label]of [['kg','Kilograms (kg)'],['lb','Pounds (lb)']]){const option=document.createElement('option');option.value=value;option.textContent=label;unit.append(option)}
    unit.value=GymTracking.weightUnit({weightUnit:r.weightUnit||GymProfile.value.weightUnit});
    unit.onchange=()=>{r.weightUnit=unit.value;r.weightKind=assistance?'assistance':'load';save()};unitLabel.append(unit);fields.append(unitLabel);
  }
  if(GymTracking.supportsDistance(r,e)){
    const distanceLabel=document.createElement('label');distanceLabel.className='distance-field';distanceLabel.textContent='Distance (optional) ';
    const distance=document.createElement('input');distance.type='number';distance.inputMode='decimal';distance.min='0';distance.max='100000';distance.step='any';distance.placeholder='—';distance.value=r.distance?.value??'';distance.setAttribute('aria-label','Distance for '+e.name);
    const unitLabel=document.createElement('label');unitLabel.className='distance-field';unitLabel.textContent='Distance unit ';
    const unit=document.createElement('select');unit.setAttribute('aria-label','Distance unit for '+e.name);
    for(const [value,label]of [['km','Kilometers (km)'],['mi','Miles (mi)'],['m','Meters (m)']]){const option=document.createElement('option');option.value=value;option.textContent=label;unit.append(option)}
    unit.value=r.distance?.unit||r.distanceUnit||'km';
    distance.onchange=()=>{if(distance.value===''&&!distance.validity.badInput){r.distance=null;save();return}if(!distance.checkValidity()){distance.reportValidity();return}r.distance={value:Number(distance.value),unit:unit.value};r.distanceUnit=unit.value;save()};
    unit.onchange=()=>{r.distanceUnit=unit.value;if(r.distance)r.distance.unit=unit.value;save()};
    distanceLabel.append(distance);unitLabel.append(unit);fields.append(distanceLabel,unitLabel);
  }
  const timeLabel=document.createElement('label');timeLabel.textContent='Start ';const time=document.createElement('input');time.type='time';time.value=r.time||'';
  time.setAttribute('aria-label','Optional start time for '+e.name);time.onchange=()=>{r.time=time.value;save()};timeLabel.append(time);fields.append(timeLabel);
  return fields;
}
$('add-activity').onclick=()=>{
  $('activity-date-label').textContent=new Date(selected+'T12:00:00').toLocaleDateString(undefined,{month:'short',day:'numeric'});
  $('manual-activity-form').reset();$('manual-activity-dialog').showModal();
};
$('manual-activity-cancel').onclick=()=>$('manual-activity-dialog').close();
$('manual-activity-form').onsubmit=event=>{
  event.preventDefault();if(entryMode==='done'&&selected>today){notify('Select today or a past day to log a workout.');return}
  const name=$('manual-activity-name').value.trim();if(!name)return;
  const id='activity-'+crypto.randomUUID(),tracking=$('manual-activity-tracking').value;
  records[selected]=[...rows(),{id,name,group:tracking==='time'?'Cardio & activity':'Strength',done:entryMode==='done',tracking,sets:null,reps:null,minutes:0,time:''}];
  save();$('manual-activity-dialog').close();notify('Activity added · Enter its workout details');window.GymNavigation?.show('calendar');
};
